local KTool = CS.Engine.Lib.KTool
local ActivityPtUtils = import('Game.UI.FightReady.UIActivityPt.ActivityPtUtils')
local GroceryUtils = import('Game.Grocery.GroceryUtils')
local UIModule = CS.Engine.UI.UIModule
local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local CountDownTime = 2592000 --30 * 86400 30天的秒数

local UIModule = CS.Engine.UI.UIModule
local ActivityCrisisContractShopDialog = Class("ActivityCrisisContractShopDialog")
local ActivityCrisisUtils = import('Game.Activity.CrisisContract.ActivityCrisisUtils')

function ActivityCrisisContractShopDialog:__init()
    self._shopData = {}
end

function ActivityCrisisContractShopDialog:__delete()
    self._shopData = nil
    self.controller = nil
end

function ActivityCrisisContractShopDialog:Awake()
end

function ActivityCrisisContractShopDialog:OnFocus(focus)
    if focus then
        self:RefreshCurrency()
    end
end

function ActivityCrisisContractShopDialog:OnShow()

end

function ActivityCrisisContractShopDialog:OnInitialize()
    local activityData = ActivityCrisisUtils.GetActivityCrisisMgr():GetActivityData()
    self.activityData = activityData

    local reqData = {
        activityUuid = self.activityData.id,
        activityType = self.activityData.type
    }
    GameUtils.Request(Interfaces.StoreActivityHome, reqData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        self._shopData =  checkTable(response.data)
        self.products = checkTable(self._shopData.products)
        self:Refresh(self.activityData.id)
    end)
end

function ActivityCrisisContractShopDialog:RefreshCurrency()
    local vo = ActivityCrisisUtils.GetActivityVo(self.activityData.activityContentId)
    CfUtils.RefreshTopGoods({vo.storeCornId})
end

function ActivityCrisisContractShopDialog:OnFinalize()

end


function ActivityCrisisContractShopDialog:Refresh(activityUuid)
    self._curUuid = checkNumber(activityUuid)

    self:FillSelf()

    self:StartTimeDown()
end

function ActivityCrisisContractShopDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self:FillTime()
    end, CountDownTime, false, true)
end

function ActivityCrisisContractShopDialog:FillSelf()
    self:FillShopInfo()
    self:FillTime()
end

function ActivityCrisisContractShopDialog:FillTime()
    local t = self._shopData
    local time = checkNumber(t.remainingTimes)
    CfUtils.FillText(self.TextTime2, CfUtils.GetTimeHMS(time))
end

function ActivityCrisisContractShopDialog:FillShopInfo()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(table.count(self.products), Bind(self, self.OnGetItemByIndex), nil, Bind(self, self.OnGetListItemByIndex))
    else
        self.ScrollView:SetListItemCount(table.count(self.products))
    end
end

function ActivityCrisisContractShopDialog:OnGetListItemByIndex(go)
end

function ActivityCrisisContractShopDialog:OnGetItemByIndex(go, index, row, column)
    if index < 0 then
        return nil
    end
    local data = self.products[index + 1]

    local scr = CfUtils.GetLuaScr(go, "Game.Activity.CrisisContract.Cell.ActivityCrisisContractShopCell")
    if scr then
        scr:Refresh(data, function()
            local isLocked = GroceryUtils.ProductIsLocked(data)
            if isLocked then
                GameUtils.Toast(localize("商品未解锁"))
                return
            end

            self._curInd = index + 1
            local t = {}
            for k, v in pairs(data.prices) do
                table.insert(t, {
                    current = v.current,
                    original = v.original,
                    currency = k
                })
            end
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonBuyItemDialog, parameters = {
                goodsId        = data.icon,
                goodsNum       = data.num,
                prices         = t,
                coinPrices     = data.coinPrices,
                maxBuyNum      = data.currentStock,
                rewards        = data.rewards,
                remainTime     = data.refreshTime,
                endTime        = data.nextRefreshLeftSeconds,
                refreshType    = data.refreshType,
                buyCb          = function (price, buyNum)
                    self:OnBuyItem(data.productId, price, buyNum, scr)
                end
            }})
        end)
    end
end

function ActivityCrisisContractShopDialog:OnBuyItem(productId, price, buyNum, scr)
    local requestPath = Interfaces.StoreActivityBuy

    local activityData = self.activityData
    local data = {
        productId = productId,
        num       = buyNum,
        activityUuid = self._curUuid,
        activityType = activityData.type
    }
    data.currency = price.currency
    GameUtils.Request(requestPath, data, function(request, response)
        if checkNumber(response.errCode) == 0 then
            local responseData = checkTable(response.data)
            if #responseData.rewards > 0 then
                local consume = {}

                table.insert(consume, { ["num"] = -price.current * buyNum;
                                        ["goodsId"] = price.currency; })
                GoodsUtils.DrawRewards(consume)
                GoodsUtils.DrawRewards(responseData.rewards)

                CriWareUtils.PlaySe(UISheets.UI_Menu.path, UISheets.UI_Menu.ui_shop_buy)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards } })

                if self.products[self._curInd] then
                    self.products[self._curInd].currentStock = checkNumber(self.products[self._curInd].currentStock) - buyNum
                end

                if scr then
                    scr:RefreshData(self.products[self._curInd])
                end
            end
        end
    end, function(errStr)
        if string.isEmpty(errStr) or errStr == nil then
            return
        end
        printError("store buy" .. errStr)
    end)
end


function ActivityCrisisContractShopDialog:OnClick()
    if not self._cb then
        return
    end
    self._cb()
end

function ActivityCrisisContractShopDialog:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return ActivityCrisisContractShopDialog